"use client";

import { useQuery } from "@tanstack/react-query";
import { useState } from "react";

import { fetchDashboardSummary, fetchInvoices } from "@/lib/api";
import { InvoiceStatus } from "@/lib/types";
import { SummaryCards } from "@/components/dashboard/summary-cards";
import { InvoiceTable } from "@/components/invoices/invoice-table";

const statusOptions: Array<{ label: string; value: InvoiceStatus | "all" }> = [
  { label: "All", value: "all" },
  { label: "Draft", value: "draft" },
  { label: "Sent", value: "sent" },
  { label: "Paid", value: "paid" },
  { label: "Overdue", value: "overdue" },
  { label: "Cancelled", value: "cancelled" },
];

export function DashboardScreen() {
  const [status, setStatus] = useState<InvoiceStatus | "all">("all");
  const [search, setSearch] = useState("");

  const summaryQuery = useQuery({
    queryKey: ["dashboard-summary"],
    queryFn: fetchDashboardSummary,
  });

  const invoicesQuery = useQuery({
    queryKey: ["invoices", status, search],
    queryFn: () => fetchInvoices({ status, search }),
  });

  return (
    <div className="dashboard-stack">
      <section className="hero-panel">
        <div>
          <p className="eyebrow">Overview</p>
          <h2 className="section-title">Your invoice desk</h2>
          <p className="subtle-copy">
            Review open balances, catch overdue accounts, and jump straight into the invoices that need attention.
          </p>
        </div>
      </section>

      {summaryQuery.isLoading ? (
        <section className="summary-grid">
          {Array.from({ length: 4 }).map((_, index) => (
            <div className="card skeleton" key={index} />
          ))}
        </section>
      ) : summaryQuery.isError || !summaryQuery.data ? (
        <div className="card state-card error">Unable to load summary data.</div>
      ) : (
        <SummaryCards summary={summaryQuery.data} />
      )}

      <section className="card panel">
        <div className="panel-heading">
          <div>
            <p className="eyebrow">Invoices</p>
            <h3 className="section-title">Recent activity</h3>
          </div>
          <div className="toolbar">
            <input
              aria-label="Search invoices"
              className="input toolbar-search"
              placeholder="Search by client or invoice number"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
            />
            <select
              className="input toolbar-select"
              value={status}
              onChange={(event) => setStatus(event.target.value as InvoiceStatus | "all")}
            >
              {statusOptions.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        <InvoiceTable
          invoices={invoicesQuery.data?.results ?? []}
          isLoading={invoicesQuery.isLoading}
          isError={invoicesQuery.isError}
        />
      </section>
    </div>
  );
}

import { DashboardSummary } from "@/lib/types";

const cards = [
  { key: "total_invoices", label: "Total invoices", note: "Across all statuses" },
  { key: "unpaid_invoices", label: "Unpaid invoices", note: "Draft, sent, and overdue" },
  { key: "overdue_invoices", label: "Overdue invoices", note: "Needs immediate follow-up" },
  { key: "total_amount_outstanding", label: "Outstanding amount", note: "Open balance still to collect" },
] as const;

export function SummaryCards({ summary }: { summary: DashboardSummary }) {
  return (
    <section className="summary-grid">
      {cards.map((card) => (
        <article className="card stat-card" key={card.key}>
          <div className="stat-card-header">
            <span>{card.label}</span>
            <small>{card.note}</small>
          </div>
          <strong>
            {card.key === "total_amount_outstanding"
              ? summary.total_amount_outstanding
              : summary[card.key].toString()}
          </strong>
        </article>
      ))}
    </section>
  );
}

"use client";

import Link from "next/link";
import { useMutation, useQuery } from "@tanstack/react-query";
import { useRouter } from "next/navigation";

import { deleteInvoice, fetchInvoice, getInvoicePdfUrl, sendReminder, updateInvoiceStatus } from "@/lib/api";
import { InvoiceStatus } from "@/lib/types";
import { StatusBadge } from "@/components/invoices/status-badge";

export function InvoiceDetail({ invoiceId }: { invoiceId: string }) {
  const router = useRouter();
  const invoiceQuery = useQuery({
    queryKey: ["invoice", invoiceId],
    queryFn: () => fetchInvoice(invoiceId),
  });

  const statusMutation = useMutation({
    mutationFn: (status: string) => updateInvoiceStatus(invoiceId, status),
    onSuccess: () => invoiceQuery.refetch(),
  });

  const reminderMutation = useMutation({
    mutationFn: () => sendReminder(invoiceId),
  });

  const deleteMutation = useMutation({
    mutationFn: () => deleteInvoice(invoiceId),
    onSuccess: () => router.push("/"),
  });

  if (invoiceQuery.isLoading) {
    return <div className="card state-card">Loading invoice...</div>;
  }

  if (invoiceQuery.isError || !invoiceQuery.data) {
    return <div className="card state-card error">Unable to load invoice.</div>;
  }

  const invoice = invoiceQuery.data;

  return (
    <div className="detail-stack">
      <section className="card detail-hero">
        <div className="detail-hero-copy">
          <p className="eyebrow">Invoice</p>
          <h2 className="section-title">{invoice.invoice_number}</h2>
          <p className="subtle-copy">
